import redis
bad=0; n=0
def val(r,k,t):
    if t=='string': return r.get(k)
    if t=='hash': return r.hgetall(k)
    if t=='list': return r.lrange(k,0,-1)
    if t=='set': return r.smembers(k)
    if t=='zset': return r.zrange(k,0,-1,withscores=True)
    if t=='stream':
        info=r.xinfo_stream(k, full=True)
        g=[]
        for gr in info.get('groups',[]):
            g.append((gr['name'],gr['last-delivered-id'],gr.get('entries-read'),
              sorted((p[0],p[1]) if isinstance(p,list) else str(p) for p in gr['pending']) if False else str(gr['pending']),
              sorted(str((c['name'],c['pel-count'],c['pending'])) for c in gr['consumers'])))
        return (r.xrange(k), info['last-generated-id'], info.get('max-deleted-entry-id'), info.get('entries-added'), info['length'], sorted(g))
    return ('?',t)
for db in range(16):
    a=redis.Redis(port=6379,db=db); b=redis.Redis(port=6380,db=db)
    ka=set(a.scan_iter(count=1000)); kb=set(b.scan_iter(count=1000))
    if ka!=kb: print('db',db,'keyset diff',len(ka-kb),len(kb-ka)); bad+=1
    for k in ka:
        n+=1
        t=a.type(k).decode(); t2=b.type(k).decode()
        if t!=t2: print('type',db,k,t,t2); bad+=1; continue
        pa=a.pttl(k); pb=b.pttl(k)
        if (pa<0)!=(pb<0) or abs(pa-pb)>5000: print('ttl',db,k,pa,pb); bad+=1
        if val(a,k,t)!=val(b,k,t): print('val',db,k,t); bad+=1
print('checked',n,'bad',bad)
EOF
